INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000801', '50000000-0000-0000-0000-000000000065', 'simple', 'mcq', 'Which pattern provides an interface for creating families of related objects?', '["Abstract Factory", "Factory Method", "Singleton", "Builder"]', 'Abstract Factory', 'Abstract Factory creates families of related objects without specifying concrete classes.', 'active'),
('60000000-0000-0000-0000-000000000802', '50000000-0000-0000-0000-000000000065', 'simple', 'mcq', 'Which creational pattern ensures a class has only one instance?', '["Singleton", "Prototype", "Builder", "Factory Method"]', 'Singleton', 'Singleton restricts instantiation to one object.', 'active'),
('60000000-0000-0000-0000-000000000803', '50000000-0000-0000-0000-000000000065', 'simple', 'mcq', 'Which pattern separates object construction from its representation?', '["Builder", "Abstract Factory", "Singleton", "Prototype"]', 'Builder', 'Builder constructs complex objects step by step.', 'active'),
('60000000-0000-0000-0000-000000000804', '50000000-0000-0000-0000-000000000065', 'simple', 'mcq', 'Which pattern creates new objects by cloning existing ones?', '["Prototype", "Factory Method", "Singleton", "Builder"]', 'Prototype', 'Prototype avoids costly creation by copying.', 'active'),
('60000000-0000-0000-0000-000000000805', '50000000-0000-0000-0000-000000000065', 'intermediate', 'mcq', 'In which scenario is Factory Method preferred over Abstract Factory?', '["When only one product family is needed", "When multiple product families exist", "For single instance control", "For cloning"]', 'When only one product family is needed', 'Factory Method defers instantiation to subclasses for one type.', 'active'),
('60000000-0000-0000-0000-000000000806', '50000000-0000-0000-0000-000000000065', 'intermediate', 'mcq', 'What problem does the Singleton pattern solve?', '["Global access to a single instance", "Object creation complexity", "Family of objects", "Cloning"]', 'Global access to a single instance', 'Provides a single point of control.', 'active'),
('60000000-0000-0000-0000-000000000807', '50000000-0000-0000-0000-000000000065', 'intermediate', 'mcq', 'Which pattern is often used for immutable objects or fluent APIs?', '["Builder", "Prototype", "Abstract Factory", "Singleton"]', 'Builder', 'Builder allows step-by-step construction with method chaining.', 'active'),
('60000000-0000-0000-0000-000000000808', '50000000-0000-0000-0000-000000000065', 'intermediate', 'mcq', 'How is deep copy typically achieved in Prototype pattern?', '["Implementing Cloneable and overriding clone()", "Shallow copy", "Serialization", "Factory"]', 'Implementing Cloneable and overriding clone()', 'Ensures independent object copies.', 'active'),
('60000000-0000-0000-0000-000000000809', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'What is a key drawback of the classic Singleton in multi-threaded environments?', '["Thread safety issues without synchronization", "Multiple instances", "High memory", "Slow cloning"]', 'Thread safety issues without synchronization', 'Requires double-checked locking or enum for safety.', 'active'),
('60000000-0000-0000-0000-000000000810', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'In which pattern is the Director responsible for construction steps?', '["Builder", "Abstract Factory", "Prototype", "Singleton"]', 'Builder', 'Director orchestrates the Builder.', 'active'),
('60000000-0000-0000-0000-000000000811', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'Which creational pattern is most violated by dependency injection frameworks?', '["Singleton", "Factory Method", "Builder", "Prototype"]', 'Singleton', 'DI promotes single instances via containers instead of class-level singletons.', 'active'),
('60000000-0000-0000-0000-000000000812', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'Why might Abstract Factory be combined with Factory Method?', '["To provide both families and deferred instantiation", "For cloning", "For single instance", "For immutability"]', 'To provide both families and deferred instantiation', 'Combines flexibility of both.', 'active'),
('60000000-0000-0000-0000-000000000813', '50000000-0000-0000-0000-000000000065', 'expert', 'mcq', 'In modern Java, what is often preferred over traditional Singleton?', '["Enum with one instance", "Static holder class", "Both enum and holder", "Global variable"]', 'Enum with one instance', 'Enums provide serialization safety and JVM guarantee.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000814', '50000000-0000-0000-0000-000000000066', 'simple', 'mcq', 'Which pattern adds responsibilities to objects dynamically?', '["Decorator", "Adapter", "Facade", "Proxy"]', 'Decorator', 'Decorator wraps objects to extend behavior.', 'active'),
('60000000-0000-0000-0000-000000000815', '50000000-0000-0000-0000-000000000066', 'simple', 'mcq', 'Which pattern provides a unified interface to a set of interfaces?', '["Facade", "Adapter", "Composite", "Bridge"]', 'Facade', 'Simplifies complex subsystems.', 'active'),
('60000000-0000-0000-0000-000000000816', '50000000-0000-0000-0000-000000000066', 'simple', 'mcq', 'Which pattern treats individual objects and compositions uniformly?', '["Composite", "Decorator", "Proxy", "Flyweight"]', 'Composite', 'Allows tree structures of objects.', 'active'),
('60000000-0000-0000-0000-000000000817', '50000000-0000-0000-0000-000000000066', 'simple', 'mcq', 'Which behavioral pattern defines a family of algorithms?', '["Strategy", "Observer", "Command", "State"]', 'Strategy', 'Encapsulates interchangeable algorithms.', 'active'),
('60000000-0000-0000-0000-000000000818', '50000000-0000-0000-0000-000000000066', 'intermediate', 'mcq', 'What does the Adapter pattern convert?', '["Interface of a class into another expected interface", "Object behavior", "Algorithm family", "State transitions"]', 'Interface of a class into another expected interface', 'Makes incompatible classes work together.', 'active'),
('60000000-0000-0000-0000-000000000819', '50000000-0000-0000-0000-000000000066', 'intermediate', 'mcq', 'Which pattern decouples an abstraction from its implementation?', '["Bridge", "Composite", "Decorator", "Facade"]', 'Bridge', 'Allows independent variation of abstraction and implementation.', 'active'),
('60000000-0000-0000-0000-000000000820', '50000000-0000-0000-0000-000000000066', 'intermediate', 'mcq', 'What is the intent of the Proxy pattern?', '["Provide a surrogate or placeholder", "Share objects to reduce memory", "Notify observers", "Encapsulate request"]', 'Provide a surrogate or placeholder', 'Controls access, lazy loading, etc.', 'active'),
('60000000-0000-0000-0000-000000000821', '50000000-0000-0000-0000-000000000066', 'intermediate', 'mcq', 'Which pattern is used in event-driven systems?', '["Observer", "Strategy", "Command", "Visitor"]', 'Observer', 'Defines one-to-many dependency.', 'active'),
('60000000-0000-0000-0000-000000000822', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'In which pattern does the Flyweight share intrinsic state?', '["Flyweight", "Proxy", "Composite", "Decorator"]', 'Flyweight', 'Reduces memory by sharing common parts.', 'active'),
('60000000-0000-0000-0000-000000000823', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'What pattern encapsulates a request as an object?', '["Command", "Chain of Responsibility", "Mediator", "Memento"]', 'Command', 'Supports undo, queuing, logging.', 'active'),
('60000000-0000-0000-0000-000000000824', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'Which pattern allows adding new operations without changing classes?', '["Visitor", "Strategy", "State", "Observer"]', 'Visitor', 'Separates algorithm from object structure.', 'active'),
('60000000-0000-0000-0000-000000000825', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'How does Chain of Responsibility pass requests?', '["Along a chain of handlers", "Directly to receiver", "Through mediator", "By state change"]', 'Along a chain of handlers', 'Each handler decides to process or pass on.', 'active'),
('60000000-0000-0000-0000-000000000826', '50000000-0000-0000-0000-000000000066', 'expert', 'mcq', 'In Mediator pattern, what reduces coupling?', '["Central mediator object", "Direct communication", "Inheritance", "Composition"]', 'Central mediator object', 'Objects communicate via mediator only.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000827', '50000000-0000-0000-0000-000000000067', 'simple', 'mcq', 'Which style has a central component coordinating others?', '["Layered Architecture", "Client-Server", "MVC", "Microservices"]', 'Layered Architecture', 'Layers like presentation, business, data.', 'active'),
('60000000-0000-0000-0000-000000000828', '50000000-0000-0000-0000-000000000067', 'simple', 'mcq', 'Which architectural style is event-driven?', '["Event-Driven Architecture", "Monolithic", "Layered", "Pipe and Filter"]', 'Event-Driven Architecture', 'Components react to events.', 'active'),
('60000000-0000-0000-0000-000000000829', '50000000-0000-0000-0000-000000000067', 'simple', 'mcq', 'What does microservices architecture promote?', '["Independent deployable services", "Single codebase", "Tight coupling", "Shared database"]', 'Independent deployable services', 'Each service owns its data and deployment.', 'active'),
('60000000-0000-0000-0000-000000000830', '50000000-0000-0000-0000-000000000067', 'simple', 'mcq', 'Which style uses pipes and filters for data processing?', '["Pipe and Filter", "Client-Server", "Hexagonal", "CQRS"]', 'Pipe and Filter', 'Unix-style data transformation pipelines.', 'active'),
('60000000-0000-0000-0000-000000000831', '50000000-0000-0000-0000-000000000067', 'intermediate', 'mcq', 'What is hexagonal architecture also known as?', '["Ports and Adapters", "Layered", "Monolithic", "Event sourcing"]', 'Ports and Adapters', 'Decouples core logic from external concerns.', 'active'),
('60000000-0000-0000-0000-000000000832', '50000000-0000-0000-0000-000000000067', 'intermediate', 'mcq', 'Which style separates read and write models?', '["CQRS", "Event Sourcing", "Microkernel", "N-tier"]', 'CQRS', 'Command Query Responsibility Segregation.', 'active'),
('60000000-0000-0000-0000-000000000833', '50000000-0000-0000-0000-000000000067', 'intermediate', 'mcq', 'What is a key benefit of clean architecture?', '["Independence from frameworks and UI", "Fast deployment", "Shared state", "Monolith simplicity"]', 'Independence from frameworks and UI', 'Dependency rule: inner layers independent.', 'active'),
('60000000-0000-0000-0000-000000000834', '50000000-0000-0000-0000-000000000067', 'intermediate', 'mcq', 'Which style is best for batch processing?', '["Pipe and Filter", "Microservices", "Client-Server", "Layered"]', 'Pipe and Filter', 'Sequential transformations.', 'active'),
('60000000-0000-0000-0000-000000000835', '50000000-0000-0000-0000-000000000067', 'expert', 'mcq', 'What architectural style uses plugins or extensions?', '["Microkernel / Plugin Architecture", "Hexagonal", "CQRS", "Event-Driven"]', 'Microkernel / Plugin Architecture', 'Core + pluggable modules.', 'active'),
('60000000-0000-0000-0000-000000000836', '50000000-0000-0000-0000-000000000067', 'expert', 'mcq', 'In which style do components communicate asynchronously via messages?', '["Event-Driven", "Request-Response", "Layered", "Monolithic"]', 'Event-Driven', 'Loose coupling and scalability.', 'active'),
('60000000-0000-0000-0000-000000000837', '50000000-0000-0000-0000-000000000067', 'expert', 'mcq', 'What is domain-driven design primarily concerned with?', '["Modeling complex business domains", "Technical infrastructure", "UI design", "Database schema"]', 'Modeling complex business domains', 'Bounded contexts, aggregates, etc.', 'active'),
('60000000-0000-0000-0000-000000000838', '50000000-0000-0000-0000-000000000067', 'expert', 'mcq', 'What architectural style is most common in legacy monoliths?', '["Monolithic", "Microservices", "CQRS", "Hexagonal"]', 'Monolithic', 'Single unit of deployment.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000839', '50000000-0000-0000-0000-000000000068', 'simple', 'mcq', 'What does the "S" in SOLID stand for?', '["Single Responsibility Principle", "Simple Principle", "Structured Principle", "Static Principle"]', 'Single Responsibility Principle', 'A class should have only one reason to change.', 'active'),
('60000000-0000-0000-0000-000000000840', '50000000-0000-0000-0000-000000000068', 'simple', 'mcq', 'What does the "O" in SOLID mean?', '["Open-Closed Principle", "Object Principle", "Override Principle", "Optional Principle"]', 'Open-Closed Principle', 'Open for extension, closed for modification.', 'active'),
('60000000-0000-0000-0000-000000000841', '50000000-0000-0000-0000-000000000068', 'simple', 'mcq', 'What does the "L" in SOLID refer to?', '["Liskov Substitution Principle", "Layer Principle", "Lazy Principle", "Local Principle"]', 'Liskov Substitution Principle', 'Subtypes must be substitutable for base types.', 'active'),
('60000000-0000-0000-0000-000000000842', '50000000-0000-0000-0000-000000000068', 'intermediate', 'mcq', 'What does the "I" in SOLID stand for?', '["Interface Segregation Principle", "Inheritance Principle", "Implementation Principle", "Integration Principle"]', 'Interface Segregation Principle', 'Many client-specific interfaces better than one general-purpose.', 'active'),
('60000000-0000-0000-0000-000000000843', '50000000-0000-0000-0000-000000000068', 'intermediate', 'mcq', 'What does the "D" in SOLID mean?', '["Dependency Inversion Principle", "Data Principle", "Direct Principle", "Dynamic Principle"]', 'Dependency Inversion Principle', 'High-level modules should not depend on low-level; both depend on abstractions.', 'active'),
('60000000-0000-0000-0000-000000000844', '50000000-0000-0000-0000-000000000068', 'intermediate', 'mcq', 'Which principle says "Don''t Repeat Yourself"?', '["DRY", "KISS", "YAGNI", "SOLID"]', 'DRY', 'Every piece of knowledge should have a single representation.', 'active'),
('60000000-0000-0000-0000-000000000845', '50000000-0000-0000-0000-000000000068', 'intermediate', 'mcq', 'Which principle advocates "Keep It Simple, Stupid"?', '["KISS", "DRY", "YAGNI", "SOLID"]', 'KISS', 'Simplicity should be a key goal in design.', 'active'),
('60000000-0000-0000-0000-000000000846', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'Which principle says "You Aren''t Gonna Need It"?', '["YAGNI", "KISS", "DRY", "SOLID"]', 'YAGNI', 'Do not add functionality until it is necessary.', 'active'),
('60000000-0000-0000-0000-000000000847', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'Law of Demeter is also known as?', '["Principle of least knowledge", "Single Responsibility", "Open-Closed", "Interface Segregation"]', 'Principle of least knowledge', 'Only talk to immediate friends.', 'active'),
('60000000-0000-0000-0000-000000000848', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'Composition over Inheritance is preferred because?', '["It provides more flexibility and avoids fragile base class problem", "It is faster", "It uses less memory", "It is simpler"]', 'It provides more flexibility and avoids fragile base class problem', 'Favor object composition over class inheritance.', 'active'),
('60000000-0000-0000-0000-000000000849', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'Which SOLID principle is most violated by deep inheritance hierarchies?', '["Liskov Substitution Principle", "Single Responsibility", "Dependency Inversion", "Open-Closed"]', 'Liskov Substitution Principle', 'Subclasses often break substitutability.', 'active'),
('60000000-0000-0000-0000-000000000850', '50000000-0000-0000-0000-000000000068', 'expert', 'mcq', 'What does the Single Responsibility Principle state a class should have?', '["Only one reason to change", "Many features", "No methods", "Global state access"]', 'Only one reason to change', 'One responsibility per class.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000851', '50000000-0000-0000-0000-000000000069', 'simple', 'mcq', 'What is the main difference between vertical and horizontal scaling?', '["Vertical adds more power to one machine, horizontal adds more machines", "Vertical is cheaper, horizontal is more expensive", "Vertical uses containers, horizontal uses VMs", "There is no difference"]', 'Vertical adds more power to one machine, horizontal adds more machines', 'Vertical = scale up (CPU/RAM), Horizontal = scale out (more instances).', 'active'),
('60000000-0000-0000-0000-000000000852', '50000000-0000-0000-0000-000000000069', 'simple', 'mcq', 'Which component distributes incoming traffic across multiple servers?', '["Load Balancer", "Database", "Cache", "CDN"]', 'Load Balancer', 'Load balancers improve availability and throughput.', 'active'),
('60000000-0000-0000-0000-000000000853', '50000000-0000-0000-0000-000000000069', 'simple', 'mcq', 'What is the primary purpose of a CDN?', '["Reduce latency by serving content from edge locations", "Store session data", "Balance database load", "Encrypt traffic"]', 'Reduce latency by serving content from edge locations', 'Content Delivery Network caches static assets closer to users.', 'active'),
('60000000-0000-0000-0000-000000000854', '50000000-0000-0000-0000-000000000069', 'simple', 'mcq', 'Which technique splits data across multiple database instances?', '["Sharding", "Caching", "Replication", "Indexing"]', 'Sharding', 'Sharding partitions data to enable horizontal scaling of databases.', 'active'),
('60000000-0000-0000-0000-000000000855', '50000000-0000-0000-0000-000000000069', 'intermediate', 'mcq', 'What is a common disadvantage of read replicas in relational databases?', '["Eventual consistency for reads", "Increased write latency", "Higher storage cost", "No failover"]', 'Eventual consistency for reads', 'Replicas may lag behind the primary, leading to stale reads.', 'active'),
('60000000-0000-0000-0000-000000000856', '50000000-0000-0000-0000-000000000069', 'intermediate', 'mcq', 'Which caching strategy loads data only when requested and not found?', '["Cache-Aside / Lazy Loading", "Write-Through", "Write-Behind", "Read-Through"]', 'Cache-Aside / Lazy Loading', 'Application checks cache → miss → fetch from DB → populate cache.', 'active'),
('60000000-0000-0000-0000-000000000857', '50000000-0000-0000-0000-000000000069', 'intermediate', 'mcq', 'What does consistent hashing help achieve in distributed caching?', '["Minimize cache misses when adding/removing nodes", "Guarantee strong consistency", "Eliminate cache invalidation", "Reduce memory usage"]', 'Minimize cache misses when adding/removing nodes', 'Reduces remapping of keys during cluster changes.', 'active'),
('60000000-0000-0000-0000-000000000858', '50000000-0000-0000-0000-000000000069', 'intermediate', 'mcq', 'Which layer-7 load balancing technique routes based on URL path?', '["Path-based routing", "Round-robin", "Least connections", "IP hash"]', 'Path-based routing', 'Common in API gateways and reverse proxies.', 'active'),
('60000000-0000-0000-0000-000000000859', '50000000-0000-0000-0000-000000000069', 'expert', 'mcq', 'What is the main trade-off when using eventual consistency?', '["Higher availability and partition tolerance vs strong consistency", "Lower cost vs higher latency", "Simpler code vs complex deployment", "No trade-off"]', 'Higher availability and partition tolerance vs strong consistency', 'CAP theorem: cannot have all three in distributed systems.', 'active'),
('60000000-0000-0000-0000-000000000860', '50000000-0000-0000-0000-000000000069', 'expert', 'mcq', 'Which throttling algorithm allows bursts while enforcing average rate?', '["Token Bucket", "Leaky Bucket", "Fixed Window", "Sliding Window"]', 'Token Bucket', 'Permits short bursts up to bucket capacity.', 'active'),
('60000000-0000-0000-0000-000000000861', '50000000-0000-0000-0000-000000000069', 'expert', 'mcq', 'In database sharding, what problem does "hot shard" refer to?', '["Uneven data distribution causing overload on one shard", "Shard failure", "Cross-shard transactions", "Replication lag"]', 'Uneven data distribution causing overload on one shard', 'Requires better key design or re-sharding.', 'active'),
('60000000-0000-0000-0000-000000000862', '50000000-0000-0000-0000-000000000069', 'expert', 'mcq', 'Which metric is most important when choosing between Redis and Memcached for caching?', '["Need for data structures and persistence (Redis) vs pure speed (Memcached)", "Cost only", "Latency only", "Size only"]', 'Need for data structures and persistence (Redis) vs pure speed (Memcached)', 'Redis offers lists, sets, pub/sub, persistence; Memcached is simpler/faster for basic key-value.', 'active'),
('60000000-0000-0000-0000-000000000863', '50000000-0000-0000-0000-000000000069', 'expert', 'mcq', 'What is write-behind caching primarily used for?', '["Asynchronous writes to improve write performance", "Read acceleration", "Strong consistency", "Cache invalidation"]', 'Asynchronous writes to improve write performance', 'Cache updates DB later → reduces write latency.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000864', '50000000-0000-0000-0000-000000000070', 'simple', 'mcq', 'In a URL shortening service like TinyURL, what is used to map short keys to long URLs?', '["Key-value store", "Relational table with index", "Graph database", "Message queue"]', 'Key-value store', 'Fast lookup by short code (e.g. Redis or DynamoDB).', 'active'),
('60000000-0000-0000-0000-000000000865', '50000000-0000-0000-0000-000000000070', 'simple', 'mcq', 'What is a common way to generate unique short keys for a URL shortener?', '["Base62 encoding of an auto-increment ID", "Random 7-char string", "MD5 hash", "UUID"]', 'Base62 encoding of an auto-increment ID', 'Guarantees uniqueness and short length.', 'active'),
('60000000-0000-0000-0000-000000000866', '50000000-0000-0000-0000-000000000070', 'simple', 'mcq', 'Which component prevents abuse in a rate limiter?', '["Token bucket or sliding window counter", "Load balancer", "CDN", "Database index"]', 'Token bucket or sliding window counter', 'Limits requests per user/time window.', 'active'),
('60000000-0000-0000-0000-000000000867', '50000000-0000-0000-0000-000000000070', 'simple', 'mcq', 'In n news feed system, what is fan-out on write?', '["Push updates to followers when content is posted", "Pull updates when user refreshes", "Hybrid approach", "No updates"]', 'Push updates to followers when content is posted', 'Pre-computes feeds for active users.', 'active'),
('60000000-0000-0000-0000-000000000868', '50000000-0000-0000-0000-000000000070', 'intermediate', 'mcq', 'What is a common choice for storing counters in a distributed rate limiter?', '["Redis with Lua scripts or INCR", "SQL database", "Cassandra", "Kafka"]', 'Redis with Lua scripts or INCR', 'Atomic operations and fast expiration.', 'active'),
('60000000-0000-0000-0000-000000000869', '50000000-0000-0000-0000-000000000070', 'intermediate', 'mcq', 'In designing a chat system, which protocol is most suitable for real-time bidirectional communication?', '["WebSocket", "HTTP/2", "Long polling", "REST"]', 'WebSocket', 'Persistent connection with low overhead.', 'active'),
('60000000-0000-0000-0000-000000000870', '50000000-0000-0000-0000-000000000070', 'intermediate', 'mcq', 'For a notification system, what pattern handles offline users?', '["Fan-out on write + pull for offline", "Only push", "Only pull", "Drop notifications"]', 'Fan-out on write + pull for offline', 'Combines push efficiency with reliability.', 'active'),
('60000000-0000-0000-0000-000000000871', '50000000-0000-0000-0000-000000000070', 'intermediate', 'mcq', 'What is the main challenge in designing a global news feed ranking system?', '["Real-time personalization vs latency", "Storage size", "Database schema", "Authentication"]', 'Real-time personalization vs latency', 'Balancing ML ranking with low delay.', 'active'),
('60000000-0000-0000-0000-000000000872', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'In a URL shortener, how can you support custom vanity URLs without collisions?', '["Separate namespace or prefix check + fallback to auto-generated", "Always use custom", "Ignore collisions", "Use longer keys"]', 'Separate namespace or prefix check + fallback to auto-generated', 'Custom URLs require conflict detection.', 'active'),
('60000000-0000-0000-0000-000000000873', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'Which consistency model is usually acceptable for a distributed rate limiter?', '["Eventual consistency", "Strong consistency", "Causal consistency", "Linearizability"]', 'Eventual consistency', 'Slight over/under limiting is tolerable.', 'active'),
('60000000-0000-0000-0000-000000000874', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'In a real-time chat system, how is message ordering typically maintained?', '["Logical timestamps or hybrid logical clocks", "Physical timestamps only", "No ordering needed", "Database auto-increment"]', 'Logical timestamps or hybrid logical clocks', 'Handles out-of-order delivery in distributed systems.', 'active'),
('60000000-0000-0000-0000-000000000875', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'What is a common way to handle fan-out explosion in social media feeds?', '["Hybrid push-pull model", "Only push", "Only pull", "No fan-out"]', 'Hybrid push-pull model', 'Push to active users, pull for inactive ones.', 'active'),
('60000000-0000-0000-0000-000000000876', '50000000-0000-0000-0000-000000000070', 'expert', 'mcq', 'What is the baseline storage requirement usually estimated for as as system design?', '["Peak traffic * retention period", "Average traffic", "Disk size", "RAM size"]', 'Peak traffic * retention period', 'Ensures capacity during worst-case scenarios.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000877', '50000000-0000-0000-0000-000000000071', 'simple', 'mcq', 'Which pattern prevents cascading failures by failing fast?', '["Circuit Breaker", "Retry", "Timeout", "Bulkhead"]', 'Circuit Breaker', 'Stops requests to failing service after threshold.', 'active'),
('60000000-0000-0000-0000-000000000878', '50000000-0000-0000-0000-000000000071', 'simple', 'mcq', 'What does a timeout pattern protect against?', '["Slow or fung downstream services", "High traffic", "Data loss", "Security attacks"]', 'Slow or fung downstream services', 'Fails request after maximum wait time.', 'active'),
('60000000-0000-0000-0000-000000000879', '50000000-0000-0000-0000-000000000071', 'simple', 'mcq', 'Which pattern isolates failures in different thread pools or processes?', '["Bulkhead", "Circuit Breaker", "Retry", "Fallback"]', 'Bulkhead', 'Prevents one slow component from affecting others.', 'active'),
('60000000-0000-0000-0000-000000000880', '50000000-0000-0000-0000-000000000071', 'simple', 'mcq', 'What is exponential backoff used for?', '["Retry delays that increase over time", "Caching", "Load balancing", "Sharding"]', 'Retry delays that increase over time', 'Prevents overwhelming failing service.', 'active'),
('60000000-0000-0000-0000-000000000881', '50000000-0000-0000-0000-000000000071', 'intermediate', 'mcq', 'Which pattern provides a default response when a service fails?', '["Fallback", "Circuit Breaker", "Retry", "Timeout"]', 'Fallback', 'Improves user experience during outages.', 'active'),
('60000000-0000-0000-0000-000000000882', '50000000-0000-0000-0000-000000000071', 'intermediate', 'mcq', 'In leader election, what ensures only one node is leader?', '["Consensus algorithm (Raft, Paxos, ZooKeeper)", "Random selection", "Round-robin", "Load balancer"]', 'Consensus algorithm (Raft, Paxos, ZooKeeper)', 'Guarantees single leader in distributed systems.', 'active'),
('60000000-0000-0000-0000-000000000883', '50000000-0000-0000-0000-000000000071', 'intermediate', 'mcq', 'What is chaos engineering?', '["Intentionally injecting failures to test resilience", "Avoiding failures", "Scaling up", "Caching"]', 'Intentionally injecting failures to test resilience', 'Netflix Chaos Monkey is a famous example.', 'active'),
('60000000-0000-0000-0000-000000000884', '50000000-0000-0000-0000-000000000071', 'intermediate', 'mcq', 'Which library popularized the circuit breaker pattern in Java?', '["Hystrix / Resilience4j", "Spring Retry", "Guava", "Apache Commons"]', 'Hystrix / Resilience4j', 'Hystrix (now maintained as Resilience4j) is widely referenced.', 'active'),
('60000000-0000-0000-0000-000000000885', '50000000-0000-0000-0000-000000000071', 'expert', 'mcq', 'What state transitions does a circuit breaker typically have?', '["Closed → Open → Half-Open", "Open → Closed only", "Half-Open only", "No states"]', 'Closed → Open → Half-Open', 'Half-Open tests recovery before full close.', 'active'),
('60000000-0000-0000-0000-000000000886', '50000000-0000-0000-0000-000000000071', 'expert', 'mcq', 'In retry patterns, what is jitter used for?', '["Randomize retry delays to avoid thundering herd", "Increase speed", "Reduce memory", "Encrypt data"]', 'Randomize retry delays to avoid thundering herd', 'Prevents synchronized retries.', 'active'),
('60000000-0000-0000-0000-000000000887', '50000000-0000-0000-0000-000000000071', 'expert', 'mcq', 'Which pattern is most appropriate for isolating database connection pools per tenant?', '["Bulkhead", "Circuit Breaker", "Retry", "Timeout"]', 'Bulkhead', 'Prevents one tenant from starving others.', 'active'),
('60000000-0000-0000-0000-000000000888', '50000000-0000-0000-0000-000000000071', 'expert', 'mcq', 'What is the primary goal of graceful degradation?', '["Continue providing partial service during failure", "Full outage", "Fast recovery only", "No service"]', 'Continue providing partial service during failure', 'Better user experience than complete failure.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000889', '50000000-0000-0000-0000-000000000072', 'simple', 'mcq', 'Which pattern coordinates distributed transactions using compensating actions?', '["Saga", "2-Phase Commit", "Event Sourcing", "CQRS"]', 'Saga', 'Each step has a compensating transaction for rollback.', 'active'),
('60000000-0000-0000-0000-000000000890', '50000000-0000-0000-0000-000000000072', 'simple', 'mcq', 'What does eventual consistency prioritize in CAP theorem?', '["Availability and partition tolerance over strong consistency", "Strong consistency", "No partitions", "No availability"]', 'Availability and partition tolerance over strong consistency', 'Common in distributed systems.', 'active'),
('60000000-0000-0000-0000-000000000891', '50000000-0000-0000-0000-000000000072', 'simple', 'mcq', 'Which pattern stores state as immutable sequence of events?', '["Event Sourcing", "Saga", "CQRS", "2PC"]', 'Event Sourcing', 'Rebuilds current state by replaying events.', 'active'),
('60000000-0000-0000-0000-000000000892', '50000000-0000-0000-0000-000000000072', 'simple', 'mcq', 'What does an API Gateway typically provide?', '["Single entry point, routing, auth, rate limiting", "Database access", "Caching only", "Logging only"]', 'Single entry point, routing, auth, rate limiting', 'Simplifies client interaction with microservices.', 'active'),
('60000000-0000-0000-0000-000000000893', '50000000-0000-0000-0000-000000000072', 'intermediate', 'mcq', 'Which pattern separates read and write models for scalability?', '["CQRS", "Event Sourcing", "Saga", "Pub/Sub"]', 'CQRS', 'Allows independent scaling of reads and writes.', 'active'),
('60000000-0000-0000-0000-000000000894', '50000000-0000-0000-0000-000000000072', 'intermediate', 'mcq', 'Which communication pattern is asynchronous and decoupled?', '["Pub/Sub", "Request-Response", "RPC", "REST"]', 'Pub/Sub', 'Publishers and subscribers are unaware of each other.', 'active'),
('60000000-0000-0000-0000-000000000895', '50000000-0000-0000-0000-000000000072', 'intermediate', 'mcq', 'What ensures an operation can be safely retried without side effects?', '["Idempotency", "Consistency", "Availability", "Durability"]', 'Idempotency', 'Same request multiple times = same result.', 'active'),
('60000000-0000-0000-0000-000000000896', '50000000-0000-0000-0000-000000000072', 'intermediate', 'mcq', 'Which technology provides observability, routing, and security between microservices?', '["Service Mesh (Istio, Linkerd)", "API Gateway", "Load Balancer", "CDN"]', 'Service Mesh (Istio, Linkerd)', 'Sidecar proxies handle cross-cutting concerns.', 'active'),
('60000000-0000-0000-0000-000000000897', '50000000-0000-0000-0000-000000000072', 'expert', 'mcq', 'Why is 2-Phase Commit rarely used in microservices?', '["It blocks on coordinator failure and reduces availability", "It is too fast", "It is simple", "No coordinator needed"]', 'It blocks on coordinator failure and reduces availability', 'Single point of failure and high latency.', 'active'),
('60000000-0000-0000-0000-000000000898', '50000000-0000-0000-0000-000000000072', 'expert', 'mcq', 'In Saga pattern, which variant uses orchestrator?', '["Orchestration Saga", "Choreography Saga", "Both", "Neither"]', 'Orchestration Saga', 'Central coordinator manages flow vs decentralized choreography.', 'active'),
('60000000-0000-0000-0000-000000000899', '50000000-0000-0000-0000-000000000072', 'expert', 'mcq', 'Which pattern is often combined with CQRS to achieve scalability?', '["Event Sourcing", "Saga", "2PC", "Bulkhead"]', 'Event Sourcing', 'Events feed read models asynchronously.', 'active'),
('60000000-0000-0000-0000-000000000900', '50000000-0000-0000-0000-000000000072', 'expert', 'mcq', 'What is the main purpose of an Outbox pattern in microservices?', '["Reliable publishing of events when DB transaction succeeds", "Caching", "Load balancing", "Rate limiting"]', 'Reliable publishing of events when DB transaction succeeds', 'Ensures events are not lost on failure.', 'active');
